define(["jquery"],function($){"use strict";const EPSILON=1e-10;class MatrixCalculator{constructor(root,options){this.root=root;this.options=options;this.currentOperation=null;this.currentTarget=null}init(){this.renderGrid("a");this.renderGrid("b");this.bindEvents();if(!Object.values(this.options.operations).some(Boolean)){this.showFeedback(this.getString("nooperation"))}}bindEvents(){this.root.on("change","[data-dimension]",event=>{this.renderGrid($(event.currentTarget).data("matrix"));this.recalculate()});this.root.on("input",".matrixcalc-cell",()=>{this.recalculate()});this.root.on("click","[data-operation]",event=>{this.currentOperation=$(event.currentTarget).data("operation");this.currentTarget=null;this.root.find("[data-operation]").removeClass("active").attr("aria-pressed","false");$(event.currentTarget).addClass("active").attr("aria-pressed","true");if(["determinant","transpose","inverse"].includes(this.currentOperation)){this.root.find("[data-region='matrix-target']").removeClass("d-none");this.clearOutput();return}this.root.find("[data-region='matrix-target']").addClass("d-none");this.calculate()});this.root.on("click","[data-target-matrix]",event=>{this.currentTarget=$(event.currentTarget).data("target-matrix");this.root.find("[data-target-matrix]").removeClass("active").attr("aria-pressed","false");$(event.currentTarget).addClass("active").attr("aria-pressed","true");this.calculate()});this.root.on("click","[data-action='clear']",()=>{this.root.find(".matrixcalc-cell").val("");this.clearOutput()})}getDimensions(matrixName){return{rows:parseInt(this.root.find(`[data-matrix='${matrixName}'][data-dimension='rows']`).val(),10),cols:parseInt(this.root.find(`[data-matrix='${matrixName}'][data-dimension='cols']`).val(),10)}}captureValues(matrixName){const values={};this.root.find(`[data-matrix-grid='${matrixName}'] .matrixcalc-cell`).each(function(){const input=$(this);values[`${input.data("row")}:${input.data("col")}`]=input.val()});return values}renderGrid(matrixName){const dimensions=this.getDimensions(matrixName);const existing=this.captureValues(matrixName);const grid=$("<div>",{class:"matrixcalc-grid-wrap"});const cells=$("<div>",{class:"matrixcalc-grid"}).css("grid-template-columns",`repeat(${dimensions.cols}, minmax(0, 1fr))`);const matrixLabel=matrixName.toUpperCase();for(let row=0;row<dimensions.rows;row++){for(let col=0;col<dimensions.cols;col++){const key=`${row}:${col}`;const input=$("<input>",{type:"number",step:"any",class:"form-control matrixcalc-cell",value:existing[key]||"","aria-label":`${matrixLabel}[${row+1},${col+1}]`,"data-row":row,"data-col":col});cells.append(input)}}grid.append(cells);this.root.find(`[data-matrix-grid='${matrixName}']`).empty().append(grid)}readMatrix(matrixName){const dimensions=this.getDimensions(matrixName);const matrix=Array.from({length:dimensions.rows},()=>Array(dimensions.cols).fill(0));this.root.find(`[data-matrix-grid='${matrixName}'] .matrixcalc-cell`).each(function(){const input=$(this);const parsed=parseFloat(input.val());matrix[input.data("row")][input.data("col")]=Number.isFinite(parsed)?parsed:0});return matrix}recalculate(){if(!this.currentOperation){return}if(["determinant","transpose","inverse"].includes(this.currentOperation)&&!this.currentTarget){return}this.calculate()}calculate(){this.hideFeedback();const matrixA=this.readMatrix("a");const matrixB=this.readMatrix("b");switch(this.currentOperation){case"add":this.calculateAddition(matrixA,matrixB);break;case"multiply":this.calculateMultiplication(matrixA,matrixB);break;case"determinant":this.calculateDeterminant(this.currentTarget==="b"?matrixB:matrixA,this.currentTarget);break;case"transpose":this.calculateTranspose(this.currentTarget==="b"?matrixB:matrixA,this.currentTarget);break;case"inverse":this.calculateInverse(this.currentTarget==="b"?matrixB:matrixA,this.currentTarget);break;default:this.clearOutput()}}calculateAddition(a,b){if(a.length!==b.length||a[0].length!==b[0].length){this.showFeedback(this.getString("invaliddimensionsadd"));this.clearResultOnly();return}const result=a.map((row,i)=>row.map((value,j)=>value+b[i][j]));const steps=[];for(let i=0;i<a.length;i++){for(let j=0;j<a[0].length;j++){steps.push(`c<sub>${i+1}${j+1}</sub> = a<sub>${i+1}${j+1}</sub> + b<sub>${i+1}${j+1}</sub> = ${this.format(a[i][j])} + ${this.format(b[i][j])} = <strong>${this.format(result[i][j])}</strong>`)}}this.showResult("A + B",result);this.showSteps(steps.map(step=>this.stepHtml(step)))}calculateMultiplication(a,b){if(a[0].length!==b.length){this.showFeedback(this.getString("invaliddimensionsmultiply"));this.clearResultOnly();return}const result=Array.from({length:a.length},()=>Array(b[0].length).fill(0));const steps=[];for(let i=0;i<a.length;i++){for(let j=0;j<b[0].length;j++){const terms=[];let sum=0;for(let k=0;k<a[0].length;k++){sum+=a[i][k]*b[k][j];terms.push(`(${this.format(a[i][k])} × ${this.format(b[k][j])})`)}result[i][j]=sum;steps.push(`c<sub>${i+1}${j+1}</sub> = ${terms.join(" + ")} = <strong>${this.format(sum)}</strong>`)}}this.showResult("A × B",result);this.showSteps(steps.map(step=>this.stepHtml(step)))}calculateTranspose(matrix,matrixName){const result=Array.from({length:matrix[0].length},(_,row)=>Array.from({length:matrix.length},(_,col)=>matrix[col][row]));const label=matrixName.toUpperCase();const steps=[];for(let i=0;i<result.length;i++){for(let j=0;j<result[0].length;j++){steps.push(`${label}<sup>T</sup><sub>${i+1}${j+1}</sub> = ${label}<sub>${j+1}${i+1}</sub> = <strong>${this.format(result[i][j])}</strong>`)}}this.showResult(`${this.getString("transposeof")} ${label}`,result);this.showSteps(steps.map(step=>this.stepHtml(step)))}calculateDeterminant(matrix,matrixName){if(matrix.length!==matrix[0].length){this.showFeedback(this.getString("squarerequired"));this.clearResultOnly();return}const work=this.cloneMatrix(matrix);const steps=[this.matrixStep(`${matrixName.toUpperCase()}`,work)];let swaps=0;let determinant=1;for(let pivot=0;pivot<work.length;pivot++){let pivotRow=pivot;for(let row=pivot+1;row<work.length;row++){if(Math.abs(work[row][pivot])>Math.abs(work[pivotRow][pivot])){pivotRow=row}}if(Math.abs(work[pivotRow][pivot])<EPSILON){determinant=0;steps.push(this.stepHtml(`Pivô da coluna ${pivot+1} = 0. Logo, det(${matrixName.toUpperCase()}) = <strong>0</strong>.`));this.showScalarResult(`${this.getString("determinantof")} ${matrixName.toUpperCase()}`,0);this.showSteps(steps);return}if(pivotRow!==pivot){[work[pivot],work[pivotRow]]=[work[pivotRow],work[pivot]];swaps++;steps.push(this.operationMatrixStep(this.interpolate(this.getString("swaprows"),{a:pivot+1,b:pivotRow+1}),work))}for(let row=pivot+1;row<work.length;row++){if(Math.abs(work[row][pivot])<EPSILON){continue}const factor=work[row][pivot]/work[pivot][pivot];for(let col=pivot;col<work.length;col++){work[row][col]-=factor*work[pivot][col];if(Math.abs(work[row][col])<EPSILON){work[row][col]=0}}steps.push(this.operationMatrixStep(this.interpolate(this.getString("replacerow"),{target:row+1,factor:this.format(factor),source:pivot+1}),work))}}const diagonal=[];for(let i=0;i<work.length;i++){determinant*=work[i][i];diagonal.push(this.format(work[i][i]))}if(swaps%2!==0){determinant*=-1}determinant=this.clean(determinant);const sign=swaps%2===0?"":"−";steps.push(this.stepHtml(`det(${matrixName.toUpperCase()}) = ${sign}(${diagonal.join(" × ")}) = <strong>${this.format(determinant)}</strong>`));this.showScalarResult(`${this.getString("determinantof")} ${matrixName.toUpperCase()}`,determinant);this.showSteps(steps)}calculateInverse(matrix,matrixName){if(matrix.length!==matrix[0].length){this.showFeedback(this.getString("squarerequired"));this.clearResultOnly();return}const size=matrix.length;const left=this.cloneMatrix(matrix);const right=this.identity(size);const steps=[this.augmentedStep(`${matrixName.toUpperCase()} | I`,left,right)];for(let pivot=0;pivot<size;pivot++){let pivotRow=pivot;for(let row=pivot+1;row<size;row++){if(Math.abs(left[row][pivot])>Math.abs(left[pivotRow][pivot])){pivotRow=row}}if(Math.abs(left[pivotRow][pivot])<EPSILON){this.showFeedback(this.getString("singularmatrix"));this.clearResultOnly();this.showSteps(steps);return}if(pivotRow!==pivot){[left[pivot],left[pivotRow]]=[left[pivotRow],left[pivot]];[right[pivot],right[pivotRow]]=[right[pivotRow],right[pivot]];steps.push(this.augmentedStep(this.interpolate(this.getString("swaprows"),{a:pivot+1,b:pivotRow+1}),left,right))}const divisor=left[pivot][pivot];if(Math.abs(divisor-1)>EPSILON){for(let col=0;col<size;col++){left[pivot][col]/=divisor;right[pivot][col]/=divisor}this.cleanMatrix(left);this.cleanMatrix(right);steps.push(this.augmentedStep(this.interpolate(this.getString("dividerow"),{row:pivot+1,divisor:this.format(divisor)}),left,right))}for(let row=0;row<size;row++){if(row===pivot||Math.abs(left[row][pivot])<EPSILON){continue}const factor=left[row][pivot];for(let col=0;col<size;col++){left[row][col]-=factor*left[pivot][col];right[row][col]-=factor*right[pivot][col]}this.cleanMatrix(left);this.cleanMatrix(right);steps.push(this.augmentedStep(this.interpolate(this.getString("replacerow"),{target:row+1,factor:this.format(factor),source:pivot+1}),left,right))}}steps.push(this.stepHtml(this.getString("identityreached")));this.showResult(`${this.getString("inverseof")} ${matrixName.toUpperCase()}`,right);this.showSteps(steps)}showResult(title,matrix){this.root.find("[data-region='result-title']").text(title);this.root.find("[data-region='result']").html(this.matrixHtml(matrix));this.root.find("[data-region='result-section']").removeClass("d-none")}showScalarResult(title,value){this.root.find("[data-region='result-title']").text(title);this.root.find("[data-region='result']").html(`<div class="h4 matrixcalc-formula">${this.format(value)}</div>`);this.root.find("[data-region='result-section']").removeClass("d-none")}showSteps(steps){this.root.find("[data-region='steps']").html(steps.join(""));this.root.find("[data-region='steps-section']").removeClass("d-none")}showFeedback(message){this.root.find("[data-region='feedback']").text(message).removeClass("d-none")}hideFeedback(){this.root.find("[data-region='feedback']").addClass("d-none").text("")}clearOutput(){this.hideFeedback();this.clearResultOnly()}clearResultOnly(){this.root.find("[data-region='result-section'], [data-region='steps-section']").addClass("d-none");this.root.find("[data-region='result'], [data-region='steps']").empty()}matrixHtml(matrix){const cols=matrix[0].length;const cells=matrix.flat().map(value=>`<div class="matrixcalc-display-cell">${this.format(value)}</div>`).join("");return`<div class="matrixcalc-display-wrap"><div class="matrixcalc-display" style="grid-template-columns:repeat(${cols}, minmax(0, 1fr))">${cells}</div></div>`}matrixStep(label,matrix){return`<div class="matrixcalc-step"><div class="matrixcalc-formula mb-2">${label}</div>${this.matrixHtml(matrix)}</div>`}operationMatrixStep(operation,matrix){return`<div class="matrixcalc-step"><div class="matrixcalc-formula mb-2">${operation}</div>${this.matrixHtml(matrix)}</div>`}augmentedStep(operation,left,right){return`<div class="matrixcalc-step"><div class="matrixcalc-formula mb-2">${operation}</div><div class="matrixcalc-augmented">${this.matrixHtml(left)}<span class="matrixcalc-divider" aria-hidden="true"></span>${this.matrixHtml(right)}</div></div>`}stepHtml(content){return`<div class="matrixcalc-step matrixcalc-formula">${content}</div>`}identity(size){return Array.from({length:size},(_,row)=>Array.from({length:size},(_,col)=>row===col?1:0))}cloneMatrix(matrix){return matrix.map(row=>row.slice())}cleanMatrix(matrix){for(let row=0;row<matrix.length;row++){for(let col=0;col<matrix[row].length;col++){matrix[row][col]=this.clean(matrix[row][col])}}}clean(value){if(Math.abs(value)<EPSILON){return 0}const rounded=Math.round(value);if(Math.abs(value-rounded)<EPSILON){return rounded}return value}format(value){value=this.clean(value);if(Number.isInteger(value)){return String(value)}return parseFloat(value.toFixed(8)).toString()}getString(identifier){return M.util.get_string(identifier,"mod_matrixcalc")}interpolate(template,values){return Object.entries(values).reduce((text,[key,value])=>text.replaceAll(`{${key}}`,value),template)}}return{init:function(options){const root=$("[data-region='matrixcalc']").first();if(!root.length){return}new MatrixCalculator(root,options).init()}}});